S = "Hakeem Force Academy"
QS = [
(S, "Who were the Ashra-e-Mubashara?", ["Ten Companions of the Prophet (PBUH) given the glad tidings of Paradise in one lifetime", "The ten wives of the Prophet (PBUH)", "Ten Muslim commanders of the Battle of Badr", "Ten scribes of the Quran"], 0, "The Ashra-e-Mubashara are ten Companions whom the Prophet (PBUH) named as people of Paradise while they were alive. They include the four Rightly Guided Caliphs.", "Their names are listed in a famous hadith narrated by Abdur Rahman bin Awf and Sa'id bin Zaid.", [5209]),
(S, "In which year was the first Asia Cup cricket tournament held?", ["1980", "1984", "1986", "1990"], 1, "The first Asia Cup was played in Sharjah, UAE, in 1984. India won it.", "The Asia Cup was started by the Asian Cricket Council founders including Pakistan, India and Sri Lanka.", [2346, 759]),
(S, "Pakistan is located in which part of Asia?", ["East Asia", "South Asia", "Central Asia", "Southeast Asia"], 1, "Pakistan lies in the north-west of the South Asian region, along with India, Bangladesh, Nepal, Bhutan, Sri Lanka and others.", "Pakistan is a founding member of SAARC, the South Asian regional organization.", [772]),
(S, "Where and in which year were the first Asian Games held?", ["Tokyo, 1958", "New Delhi, 1951", "Manila, 1954", "Jakarta, 1962"], 1, "The first Asian Games were held in New Delhi, India, in 1951. Eleven countries took part.", "The Asian Games are held every four years under the Olympic Council of Asia.", [144, 45]),
(S, "Who was the head of the committee that compiled the Quran in the time of Hazrat Abu Bakr (RA)?", ["Hazrat Zaid bin Thabit (RA)", "Hazrat Ali (RA)", "Hazrat Abdullah bin Masud (RA)", "Hazrat Abu Hurairah (RA)"], 0, "After the Battle of Yamama, Hazrat Abu Bakr (RA) appointed Hazrat Zaid bin Thabit (RA), a chief scribe of revelation, to collect the Quran. He worked from written material and from the memory of huffaz.", "Zaid bin Thabit also headed the committee of Hazrat Usman (RA) that prepared standard copies of the Quran.", [1265]),
(S, "Who is the custodian of the House in the National Assembly of Pakistan?", ["The Prime Minister", "The Speaker", "The President", "The Chief Justice"], 1, "The Speaker presides over the sessions of the National Assembly and is regarded as the custodian of the House. He maintains order and decides points of procedure.", "In the Speaker's absence the Deputy Speaker presides over the House.", [1225]),
(S, "What is Hajr-e-Aswad?", ["A sacred black stone set in a corner of the Kaaba", "A well in Makkah", "A mountain near Madina", "A gate of the Prophet's Mosque"], 0, "Hajr-e-Aswad means the Black Stone. It is set in the eastern corner of the Kaaba and pilgrims start their tawaf from it.", "The Prophet (PBUH) settled the dispute among Makkan tribes about placing it by lifting it in a cloth.", [1760]),
(S, "How many atmospheric layers does the Moon have?", ["None, it has practically no atmosphere", "One", "Three", "Five"], 0, "The Moon is too small and its gravity too weak to hold an atmosphere. It has only an extremely thin exosphere that is almost a vacuum.", "Because there is no air, sound cannot travel on the Moon and the sky looks black even in daytime.", [1783, 77, 3594]),
(S, "When did the USA drop atom bombs on Japan?", ["6 and 9 August 1945", "6 and 9 July 1944", "15 and 20 August 1945", "2 September 1945 only"], 0, "The USA dropped the atom bomb on Hiroshima on 6 August 1945 and on Nagasaki on 9 August 1945.", "Japan announced its surrender soon afterwards, ending the Second World War.", [4052]),
(S, "In which region of Pakistan is Attabad Lake located?", ["Hunza valley, Gilgit-Baltistan", "Swat valley, Khyber Pakhtunkhwa", "Neelum valley, Azad Kashmir", "Kaghan valley, Khyber Pakhtunkhwa"], 0, "Attabad Lake lies in the Hunza valley of Gilgit-Baltistan near Karimabad. It was formed by a landslide that blocked the Hunza River.", "The landslide happened in January 2010 and the lake submerged part of the Karakoram Highway.", [1295, 1091, 4146]),
(S, "What is the national game of Australia, as commonly stated?", ["Cricket", "Rugby", "Hockey", "Baseball"], 0, "Cricket is commonly given as the national game of Australia. It is the most popular summer sport there.", "Australia has no officially declared national game, so sources differ; Australian rules football is also very popular.", [3582]),
(S, "After the Quran, what is the most authentic source of Islamic teachings?", ["Hadith (Sunnah of the Prophet PBUH)", "Ijma", "Qiyas", "Ijtihad"], 0, "The Hadith and Sunnah, the sayings and actions of the Prophet (PBUH), explain and complete the Quran. They are the second source of Islamic law.", "Ijma and Qiyas are usually counted as the third and fourth sources.", [3546]),
(S, "Where is the headquarters of the International Atomic Energy Agency (IAEA)?", ["Geneva", "Vienna", "New York", "Paris"], 1, "The IAEA has its headquarters in Vienna, Austria. It promotes peaceful use of nuclear energy.", "The IAEA is an independent organization that reports to the UN General Assembly and Security Council.", [4186]),
(S, "What is the average of 23 and 32?", ["27", "27.5", "28", "55"], 1, "Add the numbers: 23 + 32 = 55. Divide by 2: 55 / 2 = 27.5.", "Average equals the sum of values divided by the number of values.", [3194]),
(S, "What is the average of 28 and 36?", ["30", "34", "32", "64"], 2, "Add the numbers: 28 + 36 = 64. Divide by 2: 64 / 2 = 32.", "The average of two numbers lies exactly midway between them.", [3195]),
(S, "What is the average of 32 and 20?", ["24", "26", "28", "52"], 1, "Add the numbers: 32 + 20 = 52. Divide by 2: 52 / 2 = 26.", "Average is also called the arithmetic mean.", [3196]),
(S, "The line y = 7 is parallel to which axis?", ["x-axis", "y-axis", "z-axis", "It is parallel to neither axis"], 0, "The line y = 7 is horizontal, because every point on it has y equal to 7. A horizontal line is parallel to the x-axis.", "The line x = 7 would be vertical and parallel to the y-axis.", [2097, 819, 5283]),
(S, "What is the y-axis also called in the coordinate plane?", ["Abscissa axis", "Ordinate axis", "Origin axis", "Quadrant axis"], 1, "The vertical y-axis is called the ordinate axis and the y-coordinate is the ordinate. The horizontal x-axis is the abscissa axis.", "The point where both axes meet is called the origin.", [3833]),
(S, "How many times is the name of Hazrat Ayesha (RA) mentioned in the Quran?", ["Zero times", "Once", "Five times", "Ten times"], 0, "The Quran does not mention Hazrat Ayesha (RA) by name. She is referred to indirectly in some verses about the Prophet's household.", "The Prophet's wives are addressed as the Mothers of the Believers in Surah Al-Ahzab.", [1920]),
(S, "In which Surah was the incident of slander (Ifk) against Hazrat Ayesha (RA) addressed and her innocence declared?", ["Surah An-Nur", "Surah Al-Ahzab", "Surah Al-Baqarah", "Surah Yusuf"], 0, "Verses 11 to 20 of Surah An-Nur declare Hazrat Ayesha (RA) innocent of the false accusation. This is known as the incident of Ifk.", "The incident took place after the expedition of Banu Mustaliq.", [2317]),
(S, "According to the 14 Points of Quaid-e-Azam, what form of government should India have?", ["A federation with residuary powers vested in the provinces", "A unitary system with a strong centre", "A monarchy", "A confederation of princely states"], 0, "The 14 Points demanded that the future constitution of India be federal. The residuary powers were to remain with the provinces.", "Quaid-e-Azam presented the 14 Points in March 1929 in reply to the Nehru Report.", [1398]),
]
